(function(){Webflow.push(function(){document.querySelectorAll(`[data-accordion]`).forEach(function(e){e.querySelectorAll(`[data-accordion-trigger]`).forEach(function(t){t.addEventListener(`click`,function(){let n=t.closest(`[data-accordion-item]`),r=n.classList.contains(`is-open`);e.querySelectorAll(`[data-accordion-item]`).forEach(function(e){e.classList.remove(`is-open`)}),r||n.classList.add(`is-open`)})})})})})();